import type {PropsWithChildren} from 'react'
import type {Icon} from '@primer/octicons-react'
import {ArrowLeftIcon} from '@primer/octicons-react'
import {testIdProps} from '@github-ui/test-id-props'
import {useClickAnalytics} from '@github-ui/use-analytics'
import styles from './OnboardingTipBanner.module.css'

export interface OnboardingTipBannerProps {
  link: string
  linkText: string
  heading: string
  icon: Icon
}

export function OnboardingTipBanner({
  children,
  link,
  linkText,
  heading,
  icon: IconComponent,
}: PropsWithChildren<OnboardingTipBannerProps>) {
  const {sendClickAnalyticsEvent} = useClickAnalytics()
  return (
    <div className={styles.OnboardingTipBanner}>
      <div className={styles.iconContainer} {...testIdProps('growth-onboardingTipBanner-icon')}>
        <IconComponent size={16} className={styles.icon} />
      </div>
      <div className={styles.content}>
        <a
          className={styles.returnLink}
          {...testIdProps('tip-return-link')}
          onClick={() =>
            sendClickAnalyticsEvent({
              category: 'advanced_security_onboarding_tip_banner',
              action: 'click_onboarding_tip_banner_return_link',
              label: `ref_cta:${linkText};ref_loc:repo_branches_listing;`,
            })
          }
          href={link}
        >
          <ArrowLeftIcon size={16} className={styles.arrowIcon} />
          <span>{linkText}</span>
        </a>
        <h3 className={styles.heading}>{heading}</h3>
        <span className={styles.tipMessage} {...testIdProps('tip-message')}>
          {children}
        </span>
      </div>
    </div>
  )
}
