import type {Role} from '@github-ui/role-assignments/types/role-assignments'
import type {SelectedTab} from '../types/selected-tab'
import {IS_KEY, ROLE_KEY} from '../types/selected-tab'

export function updateSelectedTab(query: string, selectedTab: SelectedTab): string {
  return updateSelectedFilter(query, IS_KEY, selectedTab)
}

export function updateSelectedRole(query: string, selectedRole: Role | null): string {
  return selectedRole
    ? updateSelectedFilter(query, ROLE_KEY, `"${selectedRole.name.toString()}"`)
    : updateSelectedFilter(query, ROLE_KEY, null)
}

function updateSelectedFilter(query: string, filterKey: string, filterValue: string | null): string {
  // Remove any "filterKey:*" tokens, handling both quoted and unquoted values
  // This regex matches:
  // - filterKey: followed by quoted string "..."
  // - filterKey: followed by unquoted non-whitespace characters
  // - optional trailing space
  const regex = new RegExp(`${filterKey}:(?:"[^"]*"|\\S*)\\s?`, 'g')
  const cleanedQuery = query.replace(regex, '').trim()
  if (!filterValue) {
    return cleanedQuery
  }

  // Prepend with the new selected filter if present
  return `${filterKey}:${filterValue} ${cleanedQuery}`.trim()
}
