import {testIdProps} from '@github-ui/test-id-props'
import {InheritedRoleOverlayButton} from './InheritedRoleOverlayButton'
import {NestingTableRow} from './NestingTable/NestingTableRow'
import {RemoveRoleAssignmentButton} from './RemoveRoleAssignmentButton'
import {
  RoleType,
  type Actor,
  type AvatarEnterprise,
  type AvatarOrg,
  type RoleAssignment,
} from '../types/role-assignments'
import getRoleIcon from '../utils/RoleIconMap'
import styles from './RoleAssignmentsRoleDescriptionRow.module.css'
import {RoleAssignmentSources} from './RoleAssignmentSources'
import {isEsm} from '../utils/role-utils'
import {useMemo, useState} from 'react'
import {InfoIcon} from '@primer/octicons-react'
import {IconButton} from '@primer/react'
import {RoleFgpsDialog} from './RoleFgpsDialog'

interface RoleAssignmentsRoleDescriptionRowProps {
  actor: Actor
  roleType?: RoleType
  roleAssignment: RoleAssignment
  hasWriteAccess: boolean
  canViewEnterpriseTeams: boolean
  avatarOrgs?: AvatarOrg[]
  avatarEnterprise?: AvatarEnterprise
}

export function RoleAssignmentsRoleDescriptionRow({
  actor,
  roleType,
  roleAssignment,
  hasWriteAccess,
  canViewEnterpriseTeams,
  avatarOrgs,
  avatarEnterprise,
}: RoleAssignmentsRoleDescriptionRowProps) {
  const {role} = roleAssignment
  const [showFgpMetadata, setShowFgpMetadata] = useState(false)

  const trailingItem = useMemo(() => {
    if (roleType === RoleType.Organization && isEsm(role)) {
      return (
        <IconButton
          key={'esm-role-info-button'}
          icon={InfoIcon}
          variant="invisible"
          aria-label={`Info about ${role.name}`}
          onClick={() => setShowFgpMetadata(true)}
          {...testIdProps('esm-role-info-button')}
        />
      )
    }
    if (hasWriteAccess) {
      if (roleAssignment.directly_assigned) {
        return (
          <RemoveRoleAssignmentButton
            key="remove-assignment-button"
            actor={actor}
            roleAssignment={roleAssignment}
            canViewEnterpriseTeams={canViewEnterpriseTeams}
          />
        )
      } else {
        return <InheritedRoleOverlayButton key="inherited-role-overlay" />
      }
    }
  }, [actor, canViewEnterpriseTeams, hasWriteAccess, role, roleAssignment, roleType])

  return (
    <>
      <NestingTableRow
        leadingIcon={
          <span className="fgColor-muted" {...testIdProps('role-icon')}>
            {getRoleIcon(roleAssignment.role.octicon)}
          </span>
        }
        title={roleAssignment.role.name}
        description={
          <span className={styles.descriptionContainer}>
            <div>{roleAssignment.role.description}</div>
            <div {...testIdProps('role-assignment-sources')} className={styles.assignedSourcesContainer}>
              <RoleAssignmentSources
                roleAssignment={roleAssignment}
                includeAssignedViaPrefix
                includeDirectSource
                linkTeams={canViewEnterpriseTeams}
                allOrganizationAvatarURLs={avatarOrgs?.map(org => org.avatarURL)}
                avatarEnterprise={avatarEnterprise}
              />
            </div>
          </span>
        }
        trailingItems={trailingItem && [trailingItem]}
        key={`actor-${actor.id}`}
      />
      {role.fgpMetadata && (
        <RoleFgpsDialog
          role={role}
          show={showFgpMetadata}
          onClose={() => {
            setShowFgpMetadata(false)
          }}
        />
      )}
    </>
  )
}
